from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parents[1]
slides=[]
def s(tag,title,lead='',cards=None,code=None,note='',kind=''):
 slides.append(dict(tag=tag,title=title,lead=lead,cards=cards or [],code=code,note=note,kind=kind))
s('IA EN EL TRABAJO / MARISTA','De hablar con la IA<br>a trabajar con ella.','Del prompt al sistema que entrega resultados.',note='[0:00–1:00] Abrir con una pregunta: ¿Quién usó IA esta semana? ¿Y quién chequeó lo que le respondió? Aclarar que no vamos a competir por escribir el mejor prompt ni a juzgar código. Veremos cómo se convierte una petición en un producto útil y revisable.',kind='hero')
s('01 / QUIÉN SOY','Antes de empezar,<br>una persona detrás del teclado.','<span data-profile="nombre">[Tu nombre]</span> · <span data-profile="rol">[Tu rol]</span>',cards=[['Mi recorrido','<span data-profile="trayectoria">[Dos frases sobre tu trayectoria]</span>'],['Mi día a día','<span data-profile="diaADia">[Qué hacés en tu trabajo actual]</span>'],['Por qué estoy aquí','Para mostrarles cómo es trabajar con IA, no solo hablar de ella.']],note='[1:00–3:00] La identidad y la experiencia se completan en perfil.js. Presentarse en 60–90 segundos: nombre, rol y recorrido. En Mi día a día, explicar el trabajo en Workbenches / Notebooks de OpenShift AI: diseñar, revisar e implementar arquitectura para uno o varios equipos, buscando soluciones a largo plazo. Toda esta información queda integrada acá, sin otra diapositiva biográfica. Distinguir trabajar en un producto de IA de usar IA para trabajar: no atribuirse usos, resultados ni cifras de productividad no confirmados. No es una declaración oficial de Red Hat. Cerrar con por qué te interesa mostrarles estas herramientas y pasar a qué significa usarlas en una empresa.')
s('02 / LA PREGUNTA','¿Qué significa<br>«usar IA en una empresa»?','No solo calcular: analizar información y explorar soluciones.',cards=[['Fuentes → comprensión','Cruzar datos, documentos y reportes. Identificar relaciones, contradicciones y qué información falta.'],['Evidencia → alternativas','Proponer soluciones y comparar sus ventajas, riesgos y supuestos para decidir con evidencia.'],['Necesidad → producto','Construir y modificar herramientas que otras personas puedan usar.']],note='[3:00–5:00] Distinguir cálculo de análisis: para calcular un KPI o actualizar un dashboard, muchas veces alcanza con un script de Python. El aporte que buscamos de la IA es trabajar con fuentes distintas, relacionar información, proponer explicaciones y explorar soluciones alternativas ante un problema que no tiene una receta cerrada. Ejemplo hipotético: cruzar ventas, reclamos y reportes de laboratorio para proponer qué investigar y comparar posibles acciones. Un patrón no demuestra una causa; cada propuesta necesita fuentes, supuestos explícitos y comprobaciones. Los cálculos siguen en código reproducible y la decisión es de la persona responsable. Estas son posibilidades de uso, no garantías de razonamiento correcto ni promesas de automatización total. Preguntar qué información necesitarían para elegir entre dos soluciones.')
s('03 / CÓMO CAMBIÓ EL FOCO','Del pedido al sistema<br>que trabaja y se comprueba.','Cinco términos para investigar. Se combinan; no se reemplazan.',code='Prompt Engineering   → cómo formulamos el pedido\nContext Engineering  → qué información tiene el modelo\nAI Agents            → modelos que usan herramientas y actúan\nHarness Engineering  → entorno, permisos y comprobaciones\nLoop Engineering     → ciclos de trabajo guiados por objetivos',note='[6:00–7:00] Presentar la ampliación del foco en los últimos años: de redactar pedidos a preparar contexto, habilitar acciones y diseñar sistemas verificables. No es una cronología rígida ni una sucesión de tecnologías que se vuelven obsoletas; son conceptos relacionados que conviven. AI Agents nombra un tipo de sistema, no otra disciplina de engineering. Los nombres quedan en inglés para que puedan buscarlos. Loop Engineering es un término emergente cuyo alcance varía: aquí se usa para diseñar ciclos orientados a un objetivo, con estado, feedback, condiciones de parada y revisión humana. Las fuentes y los términos están en fuentes.md y ALUMNOS.md. Una respuesta no es un resultado: el producto debe poder usarse y comprobarse.')
s('04 / PROMPT ENGINEERING','Prompt Engineering.','Objetivo + contexto + formato + restricciones.',code='Necesito un panel para ventas.\nMostrá ingresos y margen por producto.\nUsá estos datos y explicá tus supuestos.',note='[7:00–8:00] Un buen prompt evita ambigüedad. No ridiculizarlo: forma parte del trabajo. Pero un texto no concede acceso a archivos, no ejecuta pruebas y no garantiza que el agente respete las restricciones.')
s('05 / HARNESS ENGINEERING','Harness Engineering.','Combinar propuestas probabilísticas con cálculos y comprobaciones deterministas.',cards=[['El modelo propone (probabilístico)','Genera propuestas a partir del contexto. Una respuesta probable o convincente no es necesariamente correcta.'],['El código calcula (determinístico)','Con los mismos datos y reglas, el mismo cálculo. Fórmulas y validaciones explícitas, no cuentas improvisadas por el modelo.'],['Las pruebas contrastan (determinísticas)','Comparan con resultados esperados. Permisos y revisión humana completan el control: pasar pruebas no garantiza ausencia de errores.']],note='[8:00–10:00] Harness significa aquí el sistema que rodea al modelo. Explicar con la analogía de incorporar a alguien a un equipo: necesita información, herramientas y saber cuándo pedir ayuda. El término se usa en distintos sentidos; esta es una definición operativa para la charla. OpenAI describe este enfoque en su artículo Harness engineering. No es una profesión que sustituya automáticamente a otra. Explicar el equilibrio: el modelo es probabilístico; los cálculos y las comprobaciones controladas pueden ser deterministas. Determinista significa reproducible bajo las mismas entradas y condiciones, no necesariamente correcto: una fórmula mal definida también repite el mismo error. En ventas, el modelo puede construir el panel, pero el código calcula el margen y las pruebas lo contrastan con ejemplos esperados. En laboratorio, el código aplica los umbrales del protocolo educativo; el modelo no decide si un control fallido se puede ignorar. El harness aporta contexto, herramientas, límites y feedback. La persona define criterios y decide si la evidencia alcanza.')
s('06 / LOOP ENGINEERING','Loop Engineering.','El modelo propone; el código calcula; las pruebas contrastan; la persona decide.',code='1. Definir un objetivo y cómo comprobarlo\n2. Ejecutar un paso con herramientas\n3. Revisar el resultado y guardar el avance\n4. Elegir el siguiente paso con ese feedback\n5. Detenerse al cumplir, agotar límites o pedir ayuda',note='[10:00–11:00] Loop Engineering es un término emergente, no una taxonomía universal. No significa simplemente repetir el mismo prompt: se diseña cómo un sistema encuentra o recibe trabajo, actúa, comprueba, conserva el estado y decide la siguiente acción. Addy Osmani lo describe como un sistema que coordina ciclos por encima del harness de un agente. En esta charla mostramos un ciclo pequeño y supervisado. Definir límites de tiempo, costos, intentos y permisos, y cuándo debe intervenir una persona. No dejar al agente iterando indefinidamente ni tomar sus propias afirmaciones como prueba. Una persona decide si la evidencia es suficiente.')
s('07 / MI MESA DE TRABAJO','No cambio de profesión.<br>Cambio de ventanas.','Presentación ↔ IDE ↔ terminal ↔ navegador.',cards=[['IDE','Leo el briefing, los datos y los cambios.'],['Terminal','pi coordina el trabajo con el modelo Codex seleccionado. Las pruebas se ejecutan aquí.'],['Navegador','Compruebo lo que usaría una persona.']],note='[11:00–12:00] Cambiar de verdad al IDE y señalar las carpetas. Mostrar pi con el modelo Codex que tengas configurado; no describir pi y Codex como si fueran el mismo producto. Este paquete no configura la cuenta ni crea un sandbox. No proyectar credenciales, historial privado ni notificaciones.')
s('08 / NUESTRO ESCENARIO','Bienvenidos a NexoBio.','Una empresa ficticia. Dos equipos. La misma responsabilidad.',cards=[['Equipo comercial','¿Qué productos venden y cuáles aportan margen?'],['Laboratorio','¿Podemos interpretar esta ejecución del ensayo?'],['Datos sintéticos','Sin clientes, pacientes ni secretos empresariales.']],note='[12:00–13:00] Todos los nombres y registros de las demos son inventados. Compartimos una historia para conectar las dos carreras, no para afirmar que los flujos representan todos los procesos de una empresa biotech.')
s('09 / DEMO SOFTWARE','Vendemos más.<br>¿Ganamos más?','Un panel comercial para tomar una decisión, no para decorar una pantalla.',cards=[['Entrada','24 registros sintéticos de pedidos, enero–abril de 2026.'],['Salida','Ingresos, margen, comparación por producto y filtro regional.'],['Pregunta','¿El producto líder en ventas también lidera en margen aportado?']],note='[13:00–14:00] Abrir /demos/ventas/. Decir explícitamente que este producto de referencia está preparado y que ahora lo inspeccionaremos y modificaremos. Pedir una predicción antes de mirar la tabla. No llamarlo ganancia neta.')
s('10 / LO QUE NECESITA SABER','Los números también<br>tienen un contrato.','No dejemos que la IA invente qué significa «margen».',code='unidades netas = vendidas − devueltas\ningreso neto = unidades netas × precio\ncosto neto = unidades netas × costo\nmargen bruto = ingreso neto − costo neto\nmargen % = margen bruto / ingreso neto × 100',note='[14:00–15:00] Abrir BRIEF.md. Señalar el supuesto de recuperación íntegra del costo de devoluciones y la ausencia de gastos generales. Una empresa real puede definirlo distinto. Mostrar por qué el porcentaje global es ponderado y no una media simple de porcentajes.')
s('11 / EN DIRECTO','El producto tiene<br>que sobrevivir a una pregunta.','Abrimos datos → pedimos un cambio → ejecutamos pruebas → usamos el panel.',code='demos/ventas/BRIEF.md\ndemos/ventas/PROMPTS.md\nnode --test tests/ventas.test.mjs\nhttp://127.0.0.1:8000/demos/ventas/',note='[15:00–20:00] Mostrar un registro de data.json y una prueba con números manuales. Copiar el prompt 2 en pi, sin leer todas sus líneas en voz alta. Mientras trabaja, explicar qué herramientas está usando. Después abrir el panel, cambiar región y contrastar la tabla. Si el agente tarda más de 90 segundos sin progreso visible, pasar al respaldo; no esperar en silencio. Las instrucciones por sí solas no son permisos técnicos.')
s('12 / USTEDES ELIGEN','Un cambio chico.<br>Un resultado comprobable.','Elijan un desafío. Tiempo de trabajo en vivo: hasta 3 minutos.',cards=[['A / Filtrar por mes','Combinar mes y región sin dejar indicadores desactualizados.'],['B / Alertar','Marcar margen inferior al 20% con texto, no solo color.'],['C / Su propuesta','Un cambio chico de visualización o filtro; sin nuevos servicios.']],note='[20:00–25:00] Votar a mano alzada. Delimitar la petición antes de enviarla. Usar prompt 3 o alternativa. El agente debe ejecutar pruebas y reconocer qué revisión visual falta. Revisar personalmente que todos los indicadores cambian. Si propone algo fuera de alcance, anotarlo como siguiente iteración. No prometer que las pruebas existentes cubren cualquier cambio de UI.')
s('13 / QUÉ ACABAMOS DE MEDIR','No contamos líneas de código.','Evaluamos el producto y el camino hasta él.',cards=[['Tiempo','Desde la petición hasta un resultado revisado. No solo hasta la primera respuesta.'],['Calidad','Números correctos, flujo usable, requisitos cumplidos.'],['Límites','Qué comprobamos, qué no y quién aprueba.']],note='[25:00–26:00] No presentar la demo como un benchmark ni inventar ahorros. Si se quiere medir, anotar el tiempo real y el alcance del cambio. El trabajo humano de preparar datos y criterios también cuenta.')
s('14 / DEMO BIOTECNOLOGÍA','Una curva linda.<br>Un experimento no interpretable.','El control de calidad va antes que la conclusión.',cards=[['Entrada','Blanco, control positivo y cuatro muestras en triplicado.'],['Salida','Media, CV, causas y estado global de la ejecución.'],['Pregunta','¿Basta con que una muestra tenga poca dispersión?']],note='[26:00–27:00] Abrir laboratorio. Definir triplicado y control en lenguaje cotidiano: repetir ayuda a estimar variabilidad; el control nos dice si el sistema se comporta como esperamos. No hace falta conocimiento de biología previo. Simulación educativa, no técnica validada.')
s('15 / PROTOCOLO ANTES QUE OPINIÓN','Si falla el control,<br>no maquillamos la conclusión.','Las reglas de esta simulación son explícitas.',code='3 réplicas; ausente ≠ cero\nCV = desviación muestral / media × 100\nBlanco: media ≤ 0,10\nControl positivo: media entre 0,80 y 1,20\nCV de controles y muestras: ≤ 15%\nControl no conforme → ejecución NO INTERPRETABLE',note='[27:00–29:00] Enseñar PROTOCOLO.md y protocolo.json. Explicar CV como variación relativa, sin derivar la fórmula. Los umbrales son inventados para enseñar el flujo y no deben aplicarse a un ensayo real. Diferenciar QC individual de estado global. M03 tiene un dato ausente, no un cero.')
s('16 / EN DIRECTO','Primero la evidencia.<br>Después, si procede, interpretar.','El control positivo tiene media 0,62: está fuera del rango establecido.',code='demos/laboratorio/PROTOCOLO.md\ndemos/laboratorio/PROMPTS.md\nnode --test tests/laboratorio.test.mjs\nhttp://127.0.0.1:8000/demos/laboratorio/',note='[29:00–34:00] Mostrar estado global, luego CONTROL+, luego M01 (QC individual conforme), M02 (CV alto) y M03 (réplica ausente). Copiar prompt 2. Descargar el informe y abrir el texto. Preguntar: ¿por qué M01 no autoriza una conclusión? Porque los controles globales no cumplen. No hacer inferencias sobre eficacia de tratamientos ni presencia de enfermedades.')
s('17 / DESAFÍO DEL LABORATORIO','¿Y si hacemos el criterio<br>más estricto?','Comparar CV máximo de 15% y 10% como análisis de sensibilidad.',cards=[['¿Qué creen que va a pasar?','¿Arreglará el control positivo bajar el límite de CV?'],['Pedimos','Añadir comparación, sin cambiar datos ni protocolo original.'],['Comprobamos','El control sigue fuera de rango. La ejecución continúa bloqueada.']],note='[34:00–39:00] Pedir predicción, lanzar prompt 3 y revisar ambos estados. Cambiar un umbral para explorar no significa aprobar un nuevo protocolo. Si no hay tiempo, usar la alternativa de destacar el dato ausente. Si el agente modifica datos para obtener verde, detenerlo: eso sería un fallo, no una solución.')
s('18 / MISMO MÉTODO, OTRO DOMINIO','La IA no decide<br>qué significa «correcto».','Los criterios salen del problema y de las personas responsables.',cards=[['Software','Indicadores definidos + pruebas + revisión de uso.'],['Biotecnología','Protocolo + QC + revisión científica.'],['En ambos','Contexto → herramientas → evidencia → decisión humana.']],note='[39:00–41:00] El dominio cambia qué errores importan. Saber programar ayuda a construir y verificar; saber biotecnología ayuda a elegir controles e interpretar límites. No basta con operar una herramienta. La supervisión humana también puede fallar: necesita tiempo y evidencia.')
s('19 / LO QUE NO DELEGAMOS A CIEGAS','Más capacidad.<br>También más responsabilidad.','Un agente con terminal puede hacer más cosas, incluidas cosas equivocadas.',cards=[['Datos y privacidad','Solo información autorizada. Un archivo puede contener instrucciones maliciosas.'],['Acceso y acciones','Mínimo privilegio; confirmar envíos, borrados y operaciones externas.'],['Revisión y trazabilidad','Registrar cambios, conservar fuentes y pedir ayuda ante incertidumbre.']],note='[41:00–43:00] Dar ejemplo de una celda que dice ignora el protocolo: es dato no fiable, no una nueva instrucción. Los prompts no aíslan el proceso. Este taller usa datos sintéticos y archivos locales, pero no configura aislamiento del sistema operativo. En producción hacen falta controles técnicos y políticas, no solo buenas intenciones. Referencia general: NIST AI RMF.')
s('20 / SU FUTURO','Aprendan a plantear problemas.<br>Y a reconocer buenas soluciones.','Las herramientas cambian. Estas habilidades se acumulan.',cards=[['Comprender','Usuarios, negocio, ciencia, datos y limitaciones.'],['Construir','Convertir una necesidad en un artefacto que se pueda usar.'],['Verificar','Diseñar pruebas, revisar evidencia y comunicar incertidumbre.']],note='[43:00–45:00] No decir que aprender a programar o ciencias ya no importa. Al contrario: sin fundamentos es difícil saber qué aceptar. Proponer un primer proyecto: datos públicos o sintéticos, una pregunta concreta, un producto pequeño y tres comprobaciones.')
s('21 / PARA LLEVARSE','No solo «hacé esto».<br>«Así sabremos si está bien».','Ese es el salto del prompt al sistema.',code='¿Qué resultado necesito?\n¿Qué contexto y herramientas hacen falta?\n¿Qué puede hacer sin permiso?\n¿Cómo detectamos errores?\n¿Quién revisa y decide?',note='[45:00–46:00] Pedir que cada estudiante piense una tarea de su futura carrera y responda a estas cinco preguntas. Si vamos a 45 minutos, cerrar aquí y tomar preguntas breves; reducir previamente los retos en vivo, no eliminar las advertencias de laboratorio.')
s('22 / CONVERSACIÓN','Ahora les toca preguntar.','¿Qué parte de su futuro trabajo les gustaría acelerar… y qué no delegarían?',cards=[['Lo que vimos','Un panel comercial y un informe de QC.'],['Lo que importó','Contexto, herramientas, límites y comprobaciones.'],['Lo que sigue siendo humano','Elegir objetivos, asumir responsabilidad y decidir.']],note='[46:00–55:00] Preguntas. Si preguntan por sustitución de empleos, distinguir automatización de tareas de predicciones de empleo: no afirmar certezas. Si preguntan por modelos, volver al criterio: elegir según tarea, costo, privacidad y capacidad de evaluación.')
s('23 / REFERENCIAS Y MATERIAL','Fuentes para seguir.<br>Archivos para experimentar.','Material educativo independiente. Sin afiliación con OpenAI.',cards=[['Harness engineering','OpenAI · openai.com/index/harness-engineering/'],['Experiencia personal','Adriel Paredes · OpenShift AI / Red Hat · Workbenches / Notebooks'],['Riesgos y evaluación','NIST AI RMF · nist.gov/itl/ai-risk-management-framework']],note='Diapositiva de consulta, fuera del tiempo principal. Los enlaces completos y el alcance de las fuentes están en fuentes.md. El artículo de OpenAI es una experiencia de su equipo, no una prueba universal de productividad. Los materiales y los prompts se encuentran en esta carpeta; consultar README.md. No hace falta conectarse para mostrar las diapositivas ni los respaldos.')
s('24 / GRACIAS','¡Gracias!','Escaneá el QR para llevarte la presentación, el código y las demos.',note='Cierre: dejar el QR visible para que puedan escanearlo. Repositorio público: https://github.com/adrielparedes/presentacion-ia-colegio. El QR es un recurso local; abrir GitHub requiere conexión a internet.',kind='thanks')
(ROOT/'presentacion').mkdir(exist_ok=True)
(ROOT/'presentacion/contenido.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2))
sections=[]
for i,d in enumerate(slides):
 cards=''.join('<article><span class="card-num">0'+str(j+1)+'</span><h3>'+a+'</h3><p>'+b+'</p></article>' for j,(a,b) in enumerate(d['cards']))
 body='<div class="cards">'+cards+'</div>' if cards else ''
 if d['kind']=='thanks': body+='<figure class="repo-qr"><a href="https://github.com/adrielparedes/presentacion-ia-colegio" aria-label="Abrí el repositorio de la presentación en GitHub"><img src="repositorio-qr.png" alt="Código QR al repositorio presentacion-ia-colegio en GitHub"></a><figcaption><a href="https://github.com/adrielparedes/presentacion-ia-colegio">github.com/adrielparedes/presentacion-ia-colegio</a></figcaption></figure>'
 if d['code']: body+='<pre><code>'+html.escape(d['code'])+'</code></pre>'
 sections.append(f'''<section class="slide {d['kind']}" id="s{i+1}" aria-label="Diapositiva {i+1}"><header><span class="brand">◌ <b>work / ai</b></span><span>{html.escape(d['tag'])}</span></header><div class="content"><h1>{d['title']}</h1><p class="lead">{d['lead']}</p>{body}</div><footer><span>Del prompt al resultado / NexoBio</span><span>{i+1:02} / {len(slides):02}</span></footer><aside class="notes">{html.escape(d['note'])}</aside></section>''')
css='''*{box-sizing:border-box}html,body{margin:0;background:#fff;color:#171717;font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body{overflow:hidden}.slide{width:100vw;height:100vh;padding:4.3vh 5.5vw;display:none;position:relative;flex-direction:column;background:#fff}.slide.active{display:flex}header,footer{display:flex;justify-content:space-between;align-items:center;color:#454545;font-size:clamp(10px,1.05vw,17px);letter-spacing:.08em}header{border-bottom:1px solid #888;padding-bottom:2.2vh}header .brand{color:#005c46;font-size:1.6vw;letter-spacing:-.03em}.brand b{color:#171717;font-weight:500}footer{margin-top:auto;padding-top:2vh;font-size:1vw;letter-spacing:0}.content{margin:auto 0;width:100%}h1{font-weight:550;font-size:clamp(32px,4.4vw,80px);line-height:1.08;letter-spacing:-.055em;margin:3vh 0 2.2vh;max-width:90%}.hero h1{font-size:6.3vw;max-width:100%}.hero .content:before{content:'>_';display:inline-block;font-family:monospace;color:#005c46;background:#edf5f1;border:1px solid #718b80;border-radius:15px;padding:14px 20px;font-size:2.7vw;margin-bottom:2vh}.lead{font-size:1.65vw;color:#383838;line-height:1.5;max-width:90%;margin:0 0 3.5vh}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:1.4vw}article{padding:2.2vw;border:1px solid #888;border-radius:18px;background:#f5f5f5;min-height:22vh}h3{font-size:1.65vw;letter-spacing:-.025em;margin:1.1vh 0}article p{font-size:1.35vw;line-height:1.5;color:#383838;margin:1vh 0 0}.card-num{font-family:monospace;font-size:1vw;color:#005c46}pre{white-space:pre-wrap;background:#edf5f1;border:1px solid #718b80;border-left:4px solid #005c46;padding:2.4vh 2vw;border-radius:12px;color:#17382b;font-size:1.6vw;line-height:1.6;margin:1vh 0}code{font-family:ui-monospace,SFMono-Regular,monospace}.notes{display:none;position:absolute;bottom:7vh;left:5vw;right:5vw;background:#f1eee5;color:#222;padding:22px;border-radius:12px;font-size:17px;line-height:1.5;box-shadow:0 0 0 100vmax #0008;z-index:10}body.show-notes .active .notes{display:block}#controls{position:fixed;bottom:12px;left:50%;transform:translateX(-50%);display:flex;gap:8px;opacity:0;transition:opacity .2s;z-index:20}#controls:focus-within,#controls:hover,body.controls #controls{opacity:1}#controls{max-width:96vw;flex-wrap:wrap;justify-content:center;background:#fff;padding:4px;border-radius:8px}#controls label{display:flex;align-items:center;gap:6px;font:13px system-ui}select{font:inherit;color:#171717;background:#fff;border:1px solid #666;border-radius:6px;padding:7px}button{background:#fff;color:#171717;border:1px solid #666;border-radius:8px;padding:8px 12px;cursor:pointer;font:13px system-ui}button:focus-visible{outline:3px solid #005c46}#progress{position:fixed;bottom:0;height:3px;background:#005c46;transition:width .2s}a{color:inherit}.thanks .content{text-align:center}.thanks h1,.thanks .lead{max-width:100%}.repo-qr{margin:0}.repo-qr img{display:block;width:40vh;height:40vh;margin:0 auto;image-rendering:pixelated}.repo-qr figcaption{font-size:1.6vw;margin-top:1vh}.repo-qr a:focus-visible{outline:3px solid #005c46;outline-offset:4px}@media screen{body[data-legibility="4k"] h1{font-size:4.4vw}body[data-legibility="4k"] header{font-size:1.05vw}body[data-legibility="720p"] article p{font-size:1.65vw}body[data-legibility="720p"] .lead,body[data-legibility="720p"] h3{font-size:1.9vw}body[data-legibility="720p"] pre{font-size:1.8vw}body[data-legibility="480p"] .slide{padding:3vh 4vw}body[data-legibility="480p"] h1{font-size:3.6vw;max-width:100%;margin:2vh 0}body[data-legibility="480p"] .hero h1{font-size:6vw}body[data-legibility="480p"] .hero .content:before{padding:8px 12px;margin-bottom:0}body[data-legibility="480p"] .lead{font-size:2vw;line-height:1.35;max-width:100%;margin-bottom:2vh}body[data-legibility="480p"] header,body[data-legibility="480p"] footer{font-size:1.4vw}body[data-legibility="480p"] pre{font-size:2vw;line-height:1.4;padding:1.5vh 1.5vw}body[data-legibility="480p"] header{padding-bottom:1.5vh}}@media screen and (max-width:1000px){.cards{grid-template-columns:1fr;gap:1vh}article{display:grid;grid-template-columns:auto 1fr;column-gap:1.5vw;padding:1vh 1.5vw;min-height:0;border-radius:10px}.card-num{grid-row:1 / 3;font-size:1.5vw;padding-top:.5vh}h3{font-size:2.2vw;margin:0}article p{grid-column:2;font-size:2vw;line-height:1.3;margin:.5vh 0 0}}@page{size:13.333333in 7.5in;margin:0}@media print{html,body{background:#fff;overflow:visible;width:13.333333in;-webkit-print-color-adjust:exact;print-color-adjust:exact}.slide,.slide.active{display:flex;width:13.333333in;height:7.5in;page-break-after:always;break-after:page;overflow:hidden;padding:.32in .73in}.slide:last-of-type{break-after:auto;page-break-after:auto}#controls,#progress,.notes{display:none!important}}'''
js='''let index=0;const preset=document.querySelector('#legibility');try{const saved=localStorage.getItem('legibility');if([...preset.options].some(o=>o.value===saved))preset.value=saved}catch{}document.body.dataset.legibility=preset.value;const slides=[...document.querySelectorAll('.slide')];function show(n){index=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===index);s.setAttribute('aria-hidden',i===index?'false':'true')});history.replaceState(null,'','#'+(index+1));document.querySelector('#progress').style.width=((index+1)/slides.length*100)+'%';document.title=(index+1)+' · IA en el trabajo'}
preset.onchange=()=>{document.body.dataset.legibility=preset.value;try{localStorage.setItem('legibility',preset.value)}catch{}};
document.querySelector('#prev').onclick=()=>show(index-1);document.querySelector('#next').onclick=()=>show(index+1);document.querySelector('#notes').onclick=()=>document.body.classList.toggle('show-notes');document.querySelector('#full').onclick=()=>{if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.()};document.querySelector('#print').onclick=()=>window.print();window.addEventListener('keydown',e=>{if(e.target.closest('button,select,input,textarea'))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(index+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(index-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1);if(e.key.toLowerCase()==='n')document.body.classList.toggle('show-notes');if(e.key.toLowerCase()==='f')document.querySelector('#full').click();if(e.key==='Escape')document.body.classList.remove('show-notes')});window.addEventListener('hashchange',()=>show((parseInt(location.hash.slice(1))||1)-1));let t;window.addEventListener('pointermove',()=>{document.body.classList.add('controls');clearTimeout(t);t=setTimeout(()=>document.body.classList.remove('controls'),2000)});document.querySelectorAll('[data-profile]').forEach(el=>{const val=window.PERFIL?.[el.dataset.profile];if(val)el.textContent=val});show((parseInt(location.hash.slice(1))||1)-1);'''
(ROOT/'presentacion/index.html').write_text('<!doctype html><html lang="es-AR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IA en el trabajo</title><style>'+css+'</style></head><body>'+''.join(sections)+'<nav id="controls" aria-label="Controles"><label for="legibility">Legibilidad<select id="legibility"><option value="4k">4K · estándar</option><option value="1080p" selected>1080p · estándar</option><option value="720p">720p · texto grande</option><option value="480p">480p · texto grande</option></select></label><button id="prev" aria-label="Anterior">←</button><button id="next" aria-label="Siguiente">→</button><button id="notes">Notas · N</button><button id="full">Pantalla completa · F</button><button id="print">PDF / Imprimir</button></nav><div id="progress"></div><script src="perfil.js"></script><script>'+js+'</script></body></html>')
(ROOT/'GUION.md').write_text('# Guion del ponente · 55 minutos\n\nLas notas también están en el HTML: tecla N (visibles para el público si proyectás esa pantalla). No hay una ventana de ponente privada. Para notas privadas, abrir este archivo en una pantalla no proyectada.\n\n'+ '\n\n'.join(f'## {i+1:02} · '+d['title'].replace('<br>',' ')+'\n\n'+d['note'] for i,d in enumerate(slides)))
print(f'{len(slides)} diapositivas y guion creados')
